// Bundle the existing compiled calculator without flattening CommonJS scopes.
// Its legacy flattened browser bundle contains colliding compiler helpers.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const base = path.join(root, 'damage-calc-master/calc/dist');
const modules = [];
const ids = new Map();
function visit(file) {
  file = path.resolve(file);
  if (ids.has(file)) return ids.get(file);
  const id = modules.length; ids.set(file, id); modules.push(null);
  const source = fs.readFileSync(file, 'utf8').replace(/^\/\/# sourceMappingURL=.*$/gm, '');
  const dependencies = {};
  for (const [, request] of source.matchAll(/require\(["']([^"']+)["']\)/g)) {
    if (!request.startsWith('.')) throw new Error(`Unexpected dependency ${request}`);
    let dependency = path.resolve(path.dirname(file), request);
    if (fs.existsSync(dependency + '.js')) dependency += '.js';
    else dependency = path.join(dependency, 'index.js');
    dependencies[request] = visit(dependency);
  }
  modules[id] = `[function(require,module,exports){\n${source}\n},${JSON.stringify(dependencies)}]`;
  return id;
}
async function build() {
  const entry = visit(path.join(base, 'index.js'));
  const source = `(function(){const modules=[${modules.join(',\n')}],cache={};function load(id){if(cache[id])return cache[id].exports;const module=cache[id]={exports:{}};const [fn,deps]=modules[id];fn(request=>load(deps[request]),module,module.exports);return module.exports;}window.MiloCalc=load(${entry});})();`;
  const { minify } = require('../damage-calc-master/node_modules/terser');
  const result = await minify(source);
  if (!result.code) throw new Error('Calculator bundling failed');
  const license = fs.readFileSync(path.join(root, 'damage-calc-master/LICENSE'), 'utf8');
  fs.writeFileSync(path.join(root, 'data/milo-calc.js'), `/*! Local @smogon/calc bundle. Generated by scripts/build-milo-calc.js\n${license.replace(/\*\//g, '* /')}\n*/\n${result.code}\n`);
  console.log(`Bundled ${modules.length} calculator modules for Milo-när.`);
}
build().catch(error=>{console.error(error);process.exit(1);});
